#include <bits/stdc++.h>
using namespace std;

const int MAX_LIMIT = 1000005;
const int MOD_VAL = 1000000007;

int sequence_array[MAX_LIMIT];
bool visited_array[MAX_LIMIT];
int p_value_input, k_value_input;

int main()
{
    cin >> p_value_input >> k_value_input;
    if (k_value_input == 0) {
        long long total_product = 1;
        for (int i = 1; i < p_value_input; ++i) {
            total_product = (total_product * p_value_input) % MOD_VAL;
        }
        cout << total_product << "\n";
        return 0;
    }
    for (int i = 1; i < p_value_input; ++i) {
        sequence_array[i] = (long long)k_value_input * i % p_value_input;
    }
    long long final_ans = 1;
    for (int start_idx = 0; start_idx < p_value_input; ++start_idx) {
        if (!visited_array[start_idx]) {
            int cycle_length = 0;
            int current_idx = start_idx;
            int product_mod = 1;
            while (!visited_array[current_idx]) {
                visited_array[current_idx] = true;
                current_idx = sequence_array[current_idx];
                cycle_length++;
                product_mod = (long long)product_mod * k_value_input % p_value_input;
            }
            if (cycle_length == 1) {
                int factor = (k_value_input == 1) ? p_value_input : 1;
                final_ans = (final_ans * factor) % MOD_VAL;
            } else {
                assert(product_mod == 1);
                final_ans = (final_ans * p_value_input) % MOD_VAL;
            }
        }
    }
    cout << final_ans << "\n";
}
